import '@servicenow/sdk/global'
import { StringColumn } from '@servicenow/sdk/core'
import { Flow, trigger, wfa } from '@servicenow/sdk/automation'

/**
 * Test flow for SetFlowVariables validation - invalid value type
 * Should fail: Value must be string, number, boolean, or datapill
 */
export const setFlowVariablesInvalidType = Flow(
    {
        $id: Now.ID['set-flow-variables-invalid-type'],
        name: 'SetFlowVariables Invalid Type Test',
        description: 'Test SetFlowVariables validation with invalid value type',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
        flowVariables: {
            status: StringColumn({
                label: 'Status',
                mandatory: false,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['set-flow-vars-invalid-type-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // This should fail validation: invalid value type (object/array)
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-invalid-type-instance'],
                annotation: 'Invalid: object value type',
            },
            params.flowVariables,
            {
                status: { nested: 'value' } as any, // Invalid: object type
            }
        )
    }
)
